import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type NeonFallProps = Record<string, any>;

const NeonFall: React.FC<NeonFallProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  neonColor = "#ffffff",
  lineDensity = 40,
  fallSpeedMultiplier = 1,
  tumbleSpeedMultiplier = 1,
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = frame / fps;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Background Scrolling Lines logic
  const lines = useMemo(() => {
    return Array.from({ length: lineDensity }).map((_, i) => ({
      x: random(`x-${i}`) * width,
      speed: (3 + random(`speed-${i}`) * 6) * fallSpeedMultiplier,
      opacity: 0.03 + random(`op-${i}`) * 0.1,
      width: 1 + random(`w-${i}`) * 2,
      length: 100 + random(`l-${i}`) * 300,
    }));
  }, [width, lineDensity, fallSpeedMultiplier]);

  const totalHeight = height + 1000;

  // Global Tumbling and Falling Motion
  const yPos = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [height * 0.4, height * 0.6]
  );
  
  const rotation = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [0, 180 * tumbleSpeedMultiplier]
  );
  
  // Adds a slight organic rocking motion to the main rotation
  const tumble = rotation + Math.sin(t * 1.5) * 10;

  // Procedural Flailing Joint Angles
  // Multipliers are slightly disjoint to create an organic, unpredictable flailing loop
  const uArm1Angle = -60 + Math.sin(t * 2.1) * 20;
  const lArm1Angle = 15 + Math.sin(t * 2.7 + 1) * 35;

  const uArm2Angle = 116 + Math.sin(t * 1.8 + 2) * 25;
  const lArm2Angle = -60 + Math.sin(t * 2.4 + 3) * 40;

  const uLeg1Angle = 0 + Math.sin(t * 2.2 + 4) * 25;
  const lLeg1Angle = 33 + Math.sin(t * 2.9 + 5) * 35;

  const uLeg2Angle = 101 + Math.sin(t * 1.9 + 6) * 20;
  const lLeg2Angle = 60 + Math.sin(t * 2.5 + 7) * 40;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* Background Scrolling Lines */}
      {lines.map((line, i) => {
        // Continuous upward scrolling loop
        const y = totalHeight - ((frame * line.speed * 2) % totalHeight);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: line.x,
              top: y - line.length,
              width: line.width,
              height: line.length,
              backgroundColor: neonColor,
              opacity: line.opacity,
              boxShadow: `0 0 10px ${neonColor}`,
              transition: "none",
            }}
          />
        );
      })}

      {/* Flailing Falling Stick Figure */}
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", top: 0, left: 0, transition: "none" }}
      >
        <defs>
          {/* 
            This filter creates the hollow, glowing neon effect by:
            1. Taking the solid stick figure alpha mask.
            2. Expanding it outwards (dilate).
            3. Subtracting the original solid center (composite out) to create a hollow transparent ring.
            4. Applying multiple blurs to create a bright core with soft glowing light.
          */}
          <filter id="neon-outline" x="-100%" y="-100%" width="300%" height="300%">
            <feMorphology in="SourceAlpha" operator="dilate" radius="5" result="dilated" />
            <feComposite in="dilated" in2="SourceAlpha" operator="out" result="outline" />
            
            <feFlood floodColor={neonColor} result="color" />
            <feComposite in="color" in2="outline" operator="in" result="coloredOutline" />
            
            <feGaussianBlur in="coloredOutline" stdDeviation="2" result="blur1" />
            <feGaussianBlur in="coloredOutline" stdDeviation="6" result="blur2" />
            <feGaussianBlur in="coloredOutline" stdDeviation="12" result="blur3" />
            
            <feMerge>
              <feMergeNode in="blur3" />
              <feMergeNode in="blur2" />
              <feMergeNode in="blur1" />
              <feMergeNode in="coloredOutline" />
            </feMerge>
          </filter>
        </defs>

        <g
          transform={`translate(${width / 2}, ${yPos}) rotate(${tumble}) scale(1.8)`}
          filter="url(#neon-outline)"
        >
          {/* Core Skeleton Model - Solid filled to be hollowed out by the SVG filter */}
          <g
            fill="white"
            stroke="white"
            strokeWidth={16}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {/* Head */}
            <circle cx={-55} cy={-45} r={24} />
            
            {/* Spine */}
            <line x1={-30} y1={-20} x2={30} y2={40} />
            
            {/* Arm 1 (Top) */}
            <g transform={`translate(-30, -20) rotate(${uArm1Angle})`}>
              <line x1={0} y1={0} x2={45} y2={0} />
              <g transform={`translate(45, 0) rotate(${lArm1Angle})`}>
                <line x1={0} y1={0} x2={35} y2={0} />
              </g>
            </g>

            {/* Arm 2 (Bottom) */}
            <g transform={`translate(-30, -20) rotate(${uArm2Angle})`}>
              <line x1={0} y1={0} x2={45} y2={0} />
              <g transform={`translate(45, 0) rotate(${lArm2Angle})`}>
                <line x1={0} y1={0} x2={35} y2={0} />
              </g>
            </g>

            {/* Leg 1 (Top) */}
            <g transform={`translate(30, 40) rotate(${uLeg1Angle})`}>
              <line x1={0} y1={0} x2={50} y2={0} />
              <g transform={`translate(50, 0) rotate(${lLeg1Angle})`}>
                <line x1={0} y1={0} x2={45} y2={0} />
              </g>
            </g>

            {/* Leg 2 (Bottom) */}
            <g transform={`translate(30, 40) rotate(${uLeg2Angle})`}>
              <line x1={0} y1={0} x2={50} y2={0} />
              <g transform={`translate(50, 0) rotate(${lLeg2Angle})`}>
                <line x1={0} y1={0} x2={40} y2={0} />
              </g>
            </g>
          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default NeonFall;